INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$pilot$PT105-S1-Q11$pilot$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $pilot$Conclusion$pilot$, $pilot$Free will is essential to moral responsibility, but its role in determining responsibility isn't the same in every situation.$pilot$), (1, $pilot$Evidence$pilot$, $pilot$- Criminals: we hold them responsible, because they freely chose what they did.
  - Heart-attack drivers: we *don't* hold them responsible, even when a freely chosen diet could have prevented the heart attack.$pilot$), (2, $pilot$Evaluate$pilot$, $pilot$Any time we read an argument on Role or Main Conclusion, we prime ourselves: most conclusions are an opinionated first sentence or come after a pivot. This one is the first sentence, after "although."

Verify with the Support Test: *why should we believe free will's role isn't the same in all situations?* Because criminals and heart-attack drivers both made free choices that led to damage, and we treat them differently.

Now, where does the diet claim fit? It's inside the second example, and it's what makes that example work. The driver made a free choice (their diet) that led to the damage, just like a criminal. And yet we don't blame them.

Without the diet claim, the heart-attack example proves nothing. "We don't blame people for random heart attacks" doesn't show free will working differently, because there'd be no free choice in the picture at all. The diet claim sneaks free will into the heart-attack case so the contrast with criminals lands.

Is anything offered to support the diet claim? No. The author just says we have good reason to believe it. So it's a premise, not a conclusion.$pilot$), (3, $pilot$Goal$pilot$, $pilot$Prephrase one of four roles: Main Conclusion, Supports, Opposes, Neutral. This one Supports: a premise backing the main conclusion.$pilot$)) v(position,label,body) WHERE q.qid=$pilot$PT105-S1-Q11$pilot$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($pilot$A$pilot$, $pilot$A subsidiary conclusion has to be supported by something and then support something else. Ask "why should we believe a diet can affect heart attacks?" The argument never says. It's given, not concluded.$pilot$), ($pilot$B$pilot$, $pilot$The argument says we do *not* hold heart-attack drivers responsible. The diet claim helps show we don't blame them *even though* free choice was involved. (B) points it the other way.$pilot$), ($pilot$C$pilot$, $pilot$This is the most popular wrong answer, and it's the conclusion flipped. The author argues free will's role is *not* the same in all situations. The diet claim helps show the difference. (C) says it shows everything should be the same.$pilot$), ($pilot$D$pilot$, $pilot$The argument never disputes that criminals should be held responsible. It agrees they should. And the diet claim is about heart attacks, not criminals.$pilot$), ($pilot$E$pilot$, $pilot$The diet claim is support. It puts a free choice into the heart-attack example, so the example can show that free choice doesn't always lead to responsibility. That supports the main conclusion.

The most common correct answer on Role is some version of "premise." When the claim has nothing supporting it and it helps the conclusion, the plain answer is usually the right one.$pilot$)) v(letter,body) WHERE q.qid=$pilot$PT105-S1-Q11$pilot$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

